1	package release
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sync"
10		"syscall"
11	)
12	
13	const (
14		stateFileName = "ledger.json"
15		lockFileName  = "ledger.lock"
16		stateVersion  = 1
17	)
18	
19	// Store 是一个本地配方批次台账，数据保存在调用方指定的目录中。
20	// 不同目录互相独立；多个 Store 可以安全并发提交（进程内互斥、进程间文件锁）。
21	type Store struct {
22		dir      string
23		lockFile *os.File
24		mu       sync.Mutex
25		state    *persistedState
26	}
27	
28	// Open 打开（或首次使用）位于 dir 的台账。
29	// 目录不存在时会创建；目录中没有台账文件时得到空台账；
30	// 已有台账文件但无法读取或解析时返回 ErrCorruptData，不会当成空台账继续保存。
31	func Open(dir string) (*Store, error) {
32		if dir == "" {
33			return nil, errors.New("数据位置不能为空")
34		}
35		if err := os.MkdirAll(dir, 0o755); err != nil {
36			return nil, fmt.Errorf("创建数据位置 %q 失败: %w", dir, err)
37		}
38		info, err := os.Stat(dir)
39		if err != nil {
40			return nil, fmt.Errorf("读取数据位置 %q 失败: %w", dir, err)
41		}
42		if !info.IsDir() {
43			return nil, fmt.Errorf("数据位置 %q 不是目录", dir)
44		}
45	
46		lockPath := filepath.Join(dir, lockFileName)
47		lf, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
48		if err != nil {
49			return nil, fmt.Errorf("打开锁文件失败: %w", err)
50		}
51	
52		s := &Store{dir: dir, lockFile: lf}
53		if err := s.load(); err != nil {
54			lf.Close()
55			return nil, err
56		}
57		return s, nil
58	}
59	
60	// Close 释放台账占用的文件锁。
61	func (s *Store) Close() error {
62		s.mu.Lock()
63		defer s.mu.Unlock()
64		if s.lockFile == nil {
65			return nil
66		}
67		err := s.lockFile.Close()
68		s.lockFile = nil
69		return err
70	}
71	
72	func (s *Store) lockExclusive() error {
73		if s.lockFile == nil {
74			return errors.New("台账已关闭")
75		}
76		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_EX); err != nil {
77			return fmt.Errorf("锁定台账失败: %w", err)
78		}
79		return nil
80	}
81	
82	func (s *Store) lockShared() error {
83		if s.lockFile == nil {
84			return errors.New("台账已关闭")
85		}
86		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_SH); err != nil {
87			return fmt.Errorf("锁定台账失败: %w", err)
88		}
89		return nil
90	}
91	
92	func (s *Store) unlock() {
93		_ = syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_UN)
94	}
95	
96	func (s *Store) load() error {
97		data, err := os.ReadFile(filepath.Join(s.dir, stateFileName))
98		if err != nil {
99			if os.IsNotExist(err) {
100				s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
101				return nil
102			}
103			return fmt.Errorf("%w: 读取台账文件失败: %v", ErrCorruptData, err)
104		}
105		if len(data) == 0 {
106			s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
107			return nil
108		}
109		var st persistedState
110		if err := json.Unmarshal(data, &st); err != nil {
111			return fmt.Errorf("%w: 台账文件解析失败: %v", ErrCorruptData, err)
112		}
113		if st.Version != stateVersion {
114			return fmt.Errorf("%w: 台账版本 %d 不受支持", ErrCorruptData, st.Version)
115		}
116		if st.Requests == nil {
117			st.Requests = map[string]*requestRecord{}
118		}
119		s.state = &st
120		return nil
121	}
122	
123	// persist 先写临时文件再原子改名，并 fsync 目录，保证已提交数据可恢复。
124	func (s *Store) persist(st *persistedState) error {
125		data, err := json.MarshalIndent(st, "", "  ")
126		if err != nil {
127			return err
128		}
129		tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
130		f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
131		if err != nil {
132			return err
133		}
134		if _, err := f.Write(data); err != nil {
135			f.Close()
136			return err
137		}
138		if err := f.Sync(); err != nil {
139			f.Close()
140			return err
141		}
142		if err := f.Close(); err != nil {
143			return err
144		}
145		if err := os.Rename(tmpPath, filepath.Join(s.dir, stateFileName)); err != nil {
146			return err
147		}
148		if d, err := os.Open(s.dir); err == nil {
149			_ = d.Sync()
150			_ = d.Close()
151		}
152		return nil
153	}
154	
155	func cloneState(st *persistedState) (*persistedState, error) {
156		data, err := json.Marshal(st)
157		if err != nil {
158			return nil, err
159		}
160		var out persistedState
161		if err := json.Unmarshal(data, &out); err != nil {
162			return nil, err
163		}
164		if out.Requests == nil {
165			out.Requests = map[string]*requestRecord{}
166		}
167		return &out, nil
168	}
169	
170	// write 是所有写入操作的统一入口：
171	//   - reqNo 为空直接报错；
172	//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
173	//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
174	//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
175	//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
176	func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
177		if reqNo == "" {
178			return errors.New("请求编号不能为空")
179		}
180		s.mu.Lock()
181		defer s.mu.Unlock()
182		if err := s.lockExclusive(); err != nil {
183			return err
184		}
185		defer s.unlock()
186	
187		// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
188		// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
189		if err := s.load(); err != nil {
190			return err
191		}
192	
193		payloadRaw, err := json.Marshal(payload)
194		if err != nil {
195			return err
196		}
197		payloadStr := string(payloadRaw)
198	
199		if req, ok := s.state.Requests[reqNo]; ok {
200			if req.Op != op || req.Payload != payloadStr {
201				return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
202					ErrRequestConflict, reqNo, req.Op, op)
203			}
204			if err := json.Unmarshal(req.Result, out); err != nil {
205				return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
206			}
207			return nil
208		}
209	
210		clone, err := cloneState(s.state)
211		if err != nil {
212			return err
213		}
214		result, err := apply(clone)
215		if err != nil {
216			return err
217		}
218		clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
219		if err := s.persist(clone); err != nil {
220			return fmt.Errorf("保存台账失败: %w", err)
221		}
222		s.state = clone
223		if err := json.Unmarshal(result, out); err != nil {
224			return fmt.Errorf("解析请求结果失败: %w", err)
225		}
226		return nil
227	}
228	
229	// read 在共享锁下读取当前状态。
230	func (s *Store) read(fn func(*persistedState) error) error {
231		s.mu.Lock()
232		defer s.mu.Unlock()
233		if err := s.lockShared(); err != nil {
234			return err
235		}
236		defer s.unlock()
237		if err := s.load(); err != nil {
238			return err
239		}
240		return fn(s.state)
241	}
242	
243	// 视图构造：每次都从记录全新构造，返回的切片与内部状态完全隔离。
244	
245	func buildRecipeView(r *recipeRecord) *RecipeView {
246		mats := make([]MaterialView, 0, len(r.Materials))
247		for _, m := range r.Materials {
248			mats = append(mats, MaterialView{MaterialNo: m.MaterialNo, Grams: m.GramsMilli.String()})
249		}
250		return &RecipeView{RecipeNo: r.RecipeNo, Version: r.Version, Name: r.Name, Materials: mats}
251	}
252	
253	func buildBatchView(b *batchRecord, r *recipeRecord) (*BatchView, error) {
254		v := &BatchView{
255			BatchNo:         b.BatchNo,
256			RecipeNo:        r.RecipeNo,
257			RecipeVersion:   r.Version,
258			RecipeName:      r.Name,
259			PlannedPortions: b.PlannedPortions,
260			Status:          b.Status,
261			Feedings:        make([]FeedingView, 0, len(b.Feedings)),
262			Materials:       make([]MaterialRequirement, 0, len(r.Materials)),
263		}
264	
265		for _, f := range b.Feedings {
266			v.Feedings = append(v.Feedings, FeedingView{
267				Seq:        f.Seq,
268				MaterialNo: f.MaterialNo,
269				Grams:      f.GramsMilli.String(),
270				Time:       f.Time,
271				Registrar:  f.Registrar,
272			})
273		}
274	
275		for _, m := range r.Materials {
276			required, err := multiplyPortions(m.GramsMilli, b.PlannedPortions)
277			if err != nil {
278				return nil, fmt.Errorf("批次 %q 数量核对失败: %w", b.BatchNo, err)
279			}
280			act, ok := sumMaterialGrams(b, m.MaterialNo)
281			if !ok {
282				return nil, fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出可表示范围",
283					ErrCorruptData, b.BatchNo, m.MaterialNo)
284			}
285			v.Materials = append(v.Materials, MaterialRequirement{
286				MaterialNo:      m.MaterialNo,
287				RequiredGrams:   required.String(),
288				ActualGrams:     act.String(),
289				DifferenceGrams: (act - required).String(),
290			})
291		}
292		return v, nil
293	}
294	
295	func findRecipe(st *persistedState, recipeNo, version string) *recipeRecord {
296		for _, r := range st.Recipes {
297			if r.RecipeNo == recipeNo && r.Version == version {
298				return r
299			}
300		}
301		return nil
302	}
303	
304	func findBatch(st *persistedState, batchNo string) *batchRecord {
305		for _, b := range st.Batches {
306			if b.BatchNo == batchNo {
307				return b
308			}
309		}
310		return nil
311	}
312	
313	// sumMaterialGrams 统计批次内某物料已登记投料的累计千分之一克数。
314	// 仅统计该物料的记录，其他物料不参与；返回 ok=false 表示仅已有记录
315	// 的合计就已经超过可表示上限（AddFeeding 的登记前校验会阻止这种状态，
316	// 这里仍防一手整数回绕）。
317	func sumMaterialGrams(b *batchRecord, materialNo string) (sum gramsMilli, ok bool) {
318		for _, f := range b.Feedings {
319			if f.MaterialNo != materialNo {
320				continue
321			}
322			if f.GramsMilli > maxGramsMilli-sum {
323				return maxGramsMilli, false
324			}
325			sum += f.GramsMilli
326		}
327		return sum, true
328	}
