209	// 投料按成功登记的先后顺序编号，不按投料时间重排。
210	func (s *Store) AddFeeding(reqNo, batchNo, materialNo, grams string, t time.Time, registrar string) (*FeedingView, error) {
211		payload := addFeedingPayload{
212			BatchNo:    batchNo,
213			MaterialNo: materialNo,
214			Grams:      grams,
215			Time:       t,
216			Registrar:  registrar,
217		}
218		var out FeedingView
219		err := s.write(reqNo, opAddFeeding, payload, func(st *persistedState) (json.RawMessage, error) {
220			if materialNo == "" {
221				return nil, fmt.Errorf("%w: 物料编号不能为空", ErrInvalidInput)
222			}
223			if registrar == "" {
224				return nil, fmt.Errorf("%w: 登记人不能为空", ErrInvalidInput)
225			}
226			milli, err := parseGrams(grams)
227			if err != nil {
228				return nil, fmt.Errorf("%w: 物料 %q 的克数: %v", ErrInvalidInput, materialNo, err)
229			}
230			b := findBatch(st, batchNo)
231			if b == nil {
232				return nil, fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
233			}
234			if b.Status != StatusExecuting {
235				return nil, fmt.Errorf("%w: 批次 %q 状态为 %s，只有执行中的批次可以投料", ErrInvalidState, batchNo, b.Status)
236			}
237			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
238			if r == nil {
239				return nil, fmt.Errorf("%w: 批次 %q 绑定的配方版本不存在", ErrCorruptData, batchNo)
240			}
241			belongs := false
242			for _, m := range r.Materials {
243				if m.MaterialNo == materialNo {
244					belongs = true
245					break
246				}
247			}
248			if !belongs {
249				return nil, fmt.Errorf("%w: 物料 %q 不在配方 %q 版本 %q 中",
250					ErrMaterialNotInRecipe, materialNo, r.RecipeNo, r.Version)
251			}
252	
253			// 上限按物料分别判断：只累计该物料已登记的投料，
254			// 其他物料的投料量不参与，也不互相抵消。
255			summed, ok := sumMaterialGrams(b, materialNo)
256			if !ok || summed > maxGramsMilli-milli {
257				return nil, fmt.Errorf("%w: 物料 %q 的数量超出范围：本次投料后累计实投将超过上限 %s 克",
258					ErrInvalidInput, materialNo, maxGramsMilli)
259			}
260	
261			seq := len(b.Feedings) + 1
262			rec := feedingRecord{
263				Seq:        seq,
264				MaterialNo: materialNo,
265				GramsMilli: milli,
266				Time:       t,
267				Registrar:  registrar,
268			}
269			view := FeedingView{
270				Seq:        seq,
271				MaterialNo: materialNo,
272				Grams:      milli.String(),
273				Time:       t,
274				Registrar:  registrar,
275			}
276			raw, err := json.Marshal(view)
277			if err != nil {
278				return nil, err
279			}
280			b.Feedings = append(b.Feedings, rec)
281			return raw, nil
282		}, &out)
283		if err != nil {
284			return nil, err
285		}
286		return &out, nil
287	}
288	
289	// GetBatch 按批次编号查询，返回未找到（ErrNotFound）时表示批次不存在。
290	// 返回内容包含所用配方版本、计划份数、状态、全部投料（登记顺序），
291	// 以及按物料逐项的应投量、累计实投量和差额；无投料的物料也会列出。
292	// 返回的视图是台账数据的副本，调用方修改不会影响台账。
293	func (s *Store) GetBatch(batchNo string) (*BatchView, error) {
294		var out *BatchView
295		err := s.read(func(st *persistedState) error {
296			b := findBatch(st, batchNo)
297			if b == nil {
298				return fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
299			}
300			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
301			if r == nil {
302				return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 不存在",
303					ErrCorruptData, batchNo, b.RecipeNo, b.RecipeVersion)
304			}
305			view, err := buildBatchView(b, r)
306			if err != nil {
307				return err
308			}
309			out = view
310			return nil
311		})
312		if err != nil {
313			return nil, err
314		}
315		return out, nil
316	}
