535			t.Fatalf("重放不应改变批次: %v %+v", err, got)
536		}
537	
538		// 开始执行后重放创建请求，返回的仍是第一次成功时的草稿视图。
539		if _, err := s.StartBatch("s1", "B1"); err != nil {
540			t.Fatal(err)
541		}
542		b3, err := s.CreateBatch("b1", "B1", "R1", "v1", 10)
543		if err != nil {
544			t.Fatal(err)
545		}
546		if b3.Status != StatusDraft {
547			t.Fatalf("重放应返回第一次成功的结果（草稿），得到状态 %s", b3.Status)
548		}
549	
550		// 投料重放：即使批次已关闭，也返回原结果且不新增。
