552		if _, err := s.AddFeeding("f1", "B1", "M1", "100", fixedTime, "张三"); err != nil {
553			t.Fatal(err)
554		}
555		if _, err := s.CloseBatch("c1", "B1"); err != nil {
556			t.Fatal(err)
557		}
558		f2, err := s.AddFeeding("f1", "B1", "M1", "100", fixedTime, "张三")
559		if err != nil {
560			t.Fatalf("关闭后重放投料失败: %v", err)
561		}
562		if f2.Seq != 1 || f2.Grams != "100" {
563			t.Fatalf("重放投料结果不正确: %+v", f2)
564		}
565		got, _ = s.GetBatch("B1")
566		if len(got.Feedings) != 1 {
567			t.Fatalf("重放不应新增投料，得到 %d 条", len(got.Feedings))
568		}
569	}
