					RecipeVersion:   "v9", // 从未登记
					PlannedPortions: 2,
					Status:          status,
				}},
			})

			s, err := Open(dir)
			if !errors.Is(err, ErrCorruptData) {
				t.Fatalf("批次缺少配方版本应返回 ErrCorruptData，得到 %v", err)
			}
			if s != nil {
				s.Close()
				t.Fatalf("损坏台账不应返回可用的 Store 对象")
			}
			msg := err.Error()
			for _, want := range []string{"B-bad", "R1", "v9"} {
